import { useState } from "react"
import { Link } from "react-router-dom"

const Signup=()=>{
    // declare the states here
    const [username, setUsername]=useState("")
    // declare the state 
    const[useremail,setEmail]=useState("")
    const[userpassword,setPassword]=useState("")
    return(
        <div className="row justify-content-center">
           <div className="col-md-6 card shadow p-3 mt-3 text-center ">
            <h1 className="text-black">signup</h1>
            {/* bind the state here  */}
            <h1>{username}</h1>
            <h1>{useremail}</h1>
            <h1>{userpassword}</h1>
            <form action="">
                <input type="text" className="form-control"  placeholder="Enter username"
                onChange={(e)=>setUsername(e.target.value)}
                /><br />
                <input type="email" className="form-control" placeholder="Enter email" 
                onChange={(e)=>setEmail(e.target.value)}/><br />
                <input type="password" className="form-control"placeholder="Enter password" 
                /><br />
                <input type="number" className="form-control" placeholder="Enter Phone"/><br />
                <input type="submit" value="signup" className="form-control bg-danger text-white" placeholder="signup"/><br />
                <p>Already have an account?<Link to="/signin">Signin</Link></p>
            </form>
           </div>

        </div>
    )
}
export default Signup
